import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8
#define THREADS_X 16
#define THREADS_Y 16

__global__ void sgemm_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K) {
    __shared__ float As[2][BK][BM + 4];
    __shared__ float Bs[2][BK][BN];
    int bx = blockIdx.x; // along N
    int by = blockIdx.y; // along M
    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15
    int tid = ty * THREADS_X + tx; // 0..255
    int warpId = tid / 32;
    int lane = tid % 32;
    int warpRow = warpId / 4; // 0..1
    int warpCol = warpId % 4; // 0..3
    int laneM = lane / 4; // 0..7
    int laneN = lane % 4; // 0..3
    const int WM = 64;
    const int WN = 32;
    int localRow = warpRow * WM + laneM * TM;
    int localCol = warpCol * WN + laneN * TN;
    float accum[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            accum[i][j] = 0.0f;
        }
    }
    int rowBase = by * BM;
    int colBase = bx * BN;
    int numKTiles = K / BK;
    int curBuf = 0;
    // Preload the first K-tile into buffer 0
    {
        int idx = tid * 4;
        int r = idx / BK;
        int c = idx % BK;
        int gRow = rowBase + r;
        int gCol = c;
        float4 tmpA = *reinterpret_cast<const float4*>(&A[gRow * K + gCol]);
        As[0][c][r] = tmpA.x;
        As[0][c + 1][r] = tmpA.y;
        As[0][c + 2][r] = tmpA.z;
        As[0][c + 3][r] = tmpA.w;
    }
    {
        int idx = tid * 4;
        int r = idx / BN;
        int c = idx % BN;
        int gRow = r;
        int gCol = colBase + c;
        float4 tmpB = *reinterpret_cast<const float4*>(&B[gRow * N + gCol]);
        *reinterpret_cast<float4*>(&Bs[0][r][c]) = tmpB;
    }
    __syncthreads();
    for (int t = 0; t < numKTiles; t++) {
        int nextBuf = curBuf ^ 1;
        // Prefetch next K-tile into the other buffer while computing on curBuf
        if (t + 1 < numKTiles) {
            int k0next = (t + 1) * BK;
            {
                int idx = tid * 4;
                int r = idx / BK;
                int c = idx % BK;
                int gRow = rowBase + r;
                int gCol = k0next + c;
                float4 tmpA = *reinterpret_cast<const float4*>(&A[gRow * K + gCol]);
                As[nextBuf][c][r] = tmpA.x;
                As[nextBuf][c + 1][r] = tmpA.y;
                As[nextBuf][c + 2][r] = tmpA.z;
                As[nextBuf][c + 3][r] = tmpA.w;
            }
            {
                int idx = tid * 4;
                int r = idx / BN;
                int c = idx % BN;
                int gRow = k0next + r;
                int gCol = colBase + c;
                float4 tmpB = *reinterpret_cast<const float4*>(&B[gRow * N + gCol]);
                *reinterpret_cast<float4*>(&Bs[nextBuf][r][c]) = tmpB;
            }
        }
        #pragma unroll
        for (int kk = 0; kk < BK; kk++) {
            float regA[TM];
            float regB[TN];
            float4 a0 = *reinterpret_cast<const float4*>(&As[curBuf][kk][localRow]);
            float4 a1 = *reinterpret_cast<const float4*>(&As[curBuf][kk][localRow + 4]);
            regA[0] = a0.x; regA[1] = a0.y; regA[2] = a0.z; regA[3] = a0.w;
            regA[4] = a1.x; regA[5] = a1.y; regA[6] = a1.z; regA[7] = a1.w;
            float4 b0 = *reinterpret_cast<const float4*>(&Bs[curBuf][kk][localCol]);
            float4 b1 = *reinterpret_cast<const float4*>(&Bs[curBuf][kk][localCol + 4]);
            regB[0] = b0.x; regB[1] = b0.y; regB[2] = b0.z; regB[3] = b0.w;
            regB[4] = b1.x; regB[5] = b1.y; regB[6] = b1.z; regB[7] = b1.w;
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    accum[i][j] += regA[i] * regB[j];
                }
            }
        }
        __syncthreads();
        curBuf = nextBuf;
    }
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        int outRow = rowBase + localRow + i;
        int outColBase0 = colBase + localCol;
        int outColBase1 = colBase + localCol + 4;
        float4 out0 = make_float4(accum[i][0], accum[i][1], accum[i][2], accum[i][3]);
        float4 out1 = make_float4(accum[i][4], accum[i][5], accum[i][6], accum[i][7]);
        *reinterpret_cast<float4*>(&C[outRow * N + outColBase0]) = out0;
        *reinterpret_cast<float4*>(&C[outRow * N + outColBase1]) = out1;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    dim3 blockDim(THREADS_X, THREADS_Y);
    dim3 gridDim(N / BN, M / BM);

    sgemm_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs square matrix multiplication (C = A * B)
    using a custom tiled CUDA SGEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda()
        B = B.cuda()
        return self.matmul.matmul_cuda(A, B)


N = 2048 * 2

def get_inputs():
    A = torch.rand(N, N)
    B = torch.rand(N, N)
    return [A, B]

def get_init_inputs():
    return []

